#include <bits/stdc++.h>
using namespace std;

#define ll long long

ll findval(vector<ll> &pref, vector<ll> &suff, ll l, ll i, ll x) {
    ll n = pref.size();
    ll taken = n - 1 - i;
    ll rangesum = pref[n - taken - 1] - (taken?pref[2 * taken - 1]:0);
    
    // cout << rangesum << endl;
    
    ll adder = ((2 * x + taken)?suff[n - 2 * x - taken]:0) - (taken?suff[n - taken]:0);
    ll sub = ((2 * taken + x)?pref[2 * taken + x - 1]:0) - (taken?pref[2 * taken - 1]:0);
    
    // cout << adder << " " << sub << endl;
    return 3 * rangesum - 3 * sub + adder;
}

void solve() {
    int n;
    cin >> n;
    std::vector<ll> a(3 * n);
    for (int i = 0; i < 3 * n; i++) {
        cin >> a[i];
    }

    sort(a.begin(), a.end());
    
    
    vector<ll> pref(3 * n), suff(3 * n);
    pref[0] = a[0];
    for (int i = 1; i < 3 * n; i++) pref[i] = pref[i - 1] + a[i];
    suff[3 * n - 1] = a[3 * n - 1];
    for (int i = 3 * n - 2; i >= 0; i--) suff[i] = suff[i + 1] + a[i];
    
    ll ans = 0;
    ll curr = 0;
    int l = 0;
    for (int i = 3 * n - 1; i >= l; i--) {
        ll bst = 0, low = 0, high = (i - l + 1) / 3;
        while (low <= high) {
            
            ll x1 = low + (high - low) / 3;
            ll x2 = high - (high - low) / 3;
            
            ll a1 = findval(pref, suff, l, i, x1);
            ll a2 = findval(pref, suff, l, i, x2);
            if (a1 > a2) {
                high = x2 - 1;
            } else if (a1 < a2) {
                low = x1 + 1;
            } else {
                low = x1 + 1;
                high = x2 - 1;
            }
            bst = max({bst, a1, a2});
        }
        
        // cout << findval(pref, suff, l, i, 1) << endl;;
        
        ans = max(ans, curr + bst);
        curr += 6 * a[i];
        ans = max(ans, curr);
        l += 2;
    }
    
    cout << ans << endl;
}

int main() {
    int t;
    cin >> t;
    while (t--) solve();
